CREATE TABLE `asignaciones_puntaje` (
  `idAsignacion` int unsigned NOT NULL AUTO_INCREMENT,
  `idPuntaje` int unsigned NOT NULL,
  `idPeriodo` int unsigned NOT NULL,
  `idDocente` smallint unsigned NOT NULL,
  `idMateria` smallint unsigned NOT NULL,
  `fecha_asignacion` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `puntos` int NOT NULL,
  `comentario` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NOT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`idAsignacion`),
  UNIQUE KEY `unique_asignacion` (`idPuntaje`,`idMateria`,`idDocente`),
  KEY `asignaciones_puntaje_idperiodo_foreign` (`idPeriodo`),
  KEY `asignaciones_puntaje_iddocente_foreign` (`idDocente`),
  KEY `asignaciones_puntaje_idmateria_foreign` (`idMateria`),
  KEY `asignaciones_puntaje_idpuntaje_idmateria_iddocente_index` (`idPuntaje`,`idMateria`,`idDocente`),
  CONSTRAINT `asignaciones_puntaje_iddocente_foreign` FOREIGN KEY (`idDocente`) REFERENCES `docente` (`idDocente`) ON DELETE CASCADE,
  CONSTRAINT `asignaciones_puntaje_idmateria_foreign` FOREIGN KEY (`idMateria`) REFERENCES `materia` (`idMateria`) ON DELETE CASCADE,
  CONSTRAINT `asignaciones_puntaje_idperiodo_foreign` FOREIGN KEY (`idPeriodo`) REFERENCES `periodos_academicos` (`idPeriodo`) ON DELETE RESTRICT,
  CONSTRAINT `asignaciones_puntaje_idpuntaje_foreign` FOREIGN KEY (`idPuntaje`) REFERENCES `puntaje` (`idPuntaje`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=260 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
