/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `actualizar_puntaje_al_insertar_deposito` AFTER INSERT ON `deposito` FOR EACH ROW BEGIN
    DECLARE puntos_a_sumar INT;
    DECLARE id_periodo_actual INT;

    -- 1️⃣ Obtenemos el ID del período activo actual
    SELECT idPeriodo INTO id_periodo_actual
    FROM periodos_academicos
    WHERE activo = 1
    LIMIT 1;

    -- Si no hay período activo, lanzamos error
    IF id_periodo_actual IS NULL THEN
        SIGNAL SQLSTATE '45000' 
        SET MESSAGE_TEXT = 'No hay un período académico activo';
    END IF;

    -- 2️⃣ Obtenemos los puntos según el tipo de basura
    SELECT puntos INTO puntos_a_sumar
    FROM tipobasura
    WHERE idTipoBasura = NEW.idTipoBasura;

    -- 3️⃣ Verificamos si ya existe un puntaje tipo "depositos" para este usuario y período
    IF EXISTS (
        SELECT 1 
        FROM puntaje 
        WHERE idUser = NEW.idUser 
          AND idPeriodo = id_periodo_actual
          AND tipo_puntaje = 'depositos'
    ) THEN
        -- Si existe, sumamos los puntos
        UPDATE puntaje
        SET puntos = puntos + puntos_a_sumar,
            updated_at = CURRENT_TIMESTAMP
        WHERE idUser = NEW.idUser 
          AND idPeriodo = id_periodo_actual
          AND tipo_puntaje = 'depositos';
    ELSE
        -- Si no existe, creamos un nuevo puntaje tipo "depositos"
        INSERT INTO puntaje (idUser, idPeriodo, puntos, tipo_puntaje, estado, created_at, updated_at)
        VALUES (NEW.idUser, id_periodo_actual, puntos_a_sumar, 'depositos', 'activo', NOW(), NOW());
    END IF;
END */;;
