--
-- Table structure for table `raspberry_events`
--

DROP TABLE IF EXISTS `raspberry_events`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `raspberry_events` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `qr_codigo` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `idTipoBasura` tinyint unsigned DEFAULT NULL,
  `tipo_basura_nombre` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `idUser` smallint unsigned DEFAULT NULL,
  `idDeposito` mediumint unsigned DEFAULT NULL,
  `status` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `message` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `meta` json DEFAULT NULL,
  `ip` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `user_agent` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `processed_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `raspberry_events_qr_codigo_index` (`qr_codigo`),
  KEY `raspberry_events_idtipobasura_index` (`idTipoBasura`),
  KEY `raspberry_events_tipo_basura_nombre_index` (`tipo_basura_nombre`),
  KEY `raspberry_events_iduser_index` (`idUser`),
  KEY `raspberry_events_iddeposito_index` (`idDeposito`),
  KEY `raspberry_events_status_index` (`status`),
  CONSTRAINT `raspberry_events_iddeposito_foreign` FOREIGN KEY (`idDeposito`) REFERENCES `deposito` (`idDeposito`) ON DELETE SET NULL,
  CONSTRAINT `raspberry_events_idtipobasura_foreign` FOREIGN KEY (`idTipoBasura`) REFERENCES `tipobasura` (`idTipoBasura`) ON DELETE SET NULL,
  CONSTRAINT `raspberry_events_iduser_foreign` FOREIGN KEY (`idUser`) REFERENCES `usuario` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=88 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

